solutions.naive:
class Solution:
    def isValid(self, s: str) -> bool:
        # Keep deleting simple valid pairs; remaining text means invalid nesting.
        changed = True
        while changed:
            old = s
            s = s.replace("()", "").replace("[]", "").replace("{}", "")
            changed = s != old
        return s == ""

solutions.better:
class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        for ch in s:
            if ch in "([{":
                stack.append(ch)
            else:
                if not stack:
                    return False
                top = stack.pop()
                # The popped opener must match the current closer.
                if (ch == ")" and top != "(") or (ch == "]" and top != "[") or (ch == "}" and top != "{"):
                    return False
        return not stack

solutions.optimal:
class Solution:
    def isValid(self, s: str) -> bool:
        pairs = {")": "(", "]": "[", "}": "{"}
        stack = []
        for ch in s:
            if ch in pairs:
                # Pop a sentinel if there is no opener, forcing a mismatch.
                if not stack or stack.pop() != pairs[ch]:
                    return False
            else:
                stack.append(ch)
        return len(stack) == 0

